"""
ui/recommendations_tab.py
==========================
Streamlit Recommendations Tab — Extension Officer output and report download.

Reads from st.session_state["last_result"] to display the Extension Officer
Agent's recommendations generated by the Orchestrator pipeline.
"""

import streamlit as st
from utils.report_generator import build_report


def render():
    """Render the Recommendations tab."""

    st.markdown("### 💡 Agricultural Recommendations")
    st.markdown(
        "Recommendations generated by the **Extension Officer Agent** based on the "
        "Pathologist Agent's crop disease diagnosis."
    )
    st.markdown("---")

    result = st.session_state.get("last_result")

    if not result:
        st.info(
            "💡 No analysis has been run yet. "
            "Go to the **Diagnosis** tab, upload a crop image, and click **Analyse Crop**."
        )
        return

    recs = result.get("recommendations", {})

    if recs.get("error"):
        st.warning(f"⚠️ Recommendation error: {recs['error']}")
        if recs.get("raw_response"):
            with st.expander("📄 Raw Model Response"):
                st.code(recs["raw_response"], language=None)
        return

    if not recs:
        st.warning("No recommendations available. Please re-run the analysis.")
        return

    # ── Diagnosis summary banner ───────────────────────────────────────────────
    diagnosis = result.get("diagnosis", {})
    disease   = diagnosis.get("disease_name", "Unknown")
    severity  = diagnosis.get("severity", "Unknown")

    sev_color = {
        "Mild":     "#2d5a27",
        "Moderate": "#856404",
        "Severe":   "#991b1b",
        "None":     "#2d5a27",
    }.get(severity, "#495057")

    st.markdown(
        f"""
        <div style="background:#f0f8ec; border:1px solid #c3ddb8; border-radius:10px;
                    padding:14px 20px; margin-bottom:20px;">
            <strong>Diagnosis:</strong> {disease} &nbsp;|&nbsp;
            <strong>Severity:</strong> <span style="color:{sev_color}; font-weight:600;">{severity}</span>
        </div>
        """,
        unsafe_allow_html=True,
    )

    # ── Four recommendation sections ──────────────────────────────────────────
    _rec_section("🌱 Treatment", recs.get("treatment", "Not available."),
                 "Immediate steps to treat the identified disease.")

    _rec_section("🛡️ Prevention", recs.get("prevention", "Not available."),
                 "Long-term measures to prevent recurrence.")

    _rec_section("⚗️ Safe Chemicals / Inputs", recs.get("safe_chemicals", "Not available."),
                 "Registered fungicides, pesticides, or biological agents safe for this crop.")

    _rec_section("📋 Farmer Advisory", recs.get("farmer_advisory", "Not available."),
                 "Important safety notes and additional guidance.", highlight=True)

    st.markdown("---")

    # ── Metrics expander ──────────────────────────────────────────────────────
    with st.expander("📊 Model Metrics"):
        m1, m2 = st.columns(2)
        m1.metric("Latency", f"{recs.get('latency_ms', 0):,.0f} ms")
        m2.metric("Tokens Used", recs.get("tokens_used", 0) or "N/A")

    with st.expander("📄 Raw Model Response"):
        st.code(recs.get("raw_response", "No response captured."), language=None)

    # ── Agricultural safety events ────────────────────────────────────────────
    agri_events = result.get("agri_safety_events", [])
    if agri_events:
        with st.expander("🌿 Agricultural Safety Checks"):
            for event in agri_events:
                icon  = "✅" if event.get("passed") else "⚠️"
                sev   = event.get("severity", "")
                layer = event.get("layer", "")
                reason = event.get("reason", "")
                # WARNING is amber, BLOCK is red, INFO/pass is green
                if not event.get("passed"):
                    st.error(f"**{icon} {layer}** [{sev}]: {reason}")
                elif sev == "WARNING":
                    st.warning(f"**{icon} {layer}** [{sev}]: {reason}")
                else:
                    st.success(f"**{icon} {layer}** [{sev}]: {reason}")

    # ── Download report ───────────────────────────────────────────────────────
    st.markdown("---")
    st.markdown("#### 📥 Download Report")

    farmer_note = st.session_state.get("last_note", "")
    report_md   = build_report(result, farmer_note)

    run_id = result.get("run_id", "report")
    st.download_button(
        label="⬇️ Download Analysis Report (.md)",
        data=report_md,
        file_name=f"agri_doctor_report_{run_id}.md",
        mime="text/markdown",
        use_container_width=True,
    )
    st.caption("Report is in Markdown format — open with any text editor or Markdown viewer.")


# ── Private helpers ───────────────────────────────────────────────────────────

def _rec_section(title: str, content: str, subtitle: str = "", highlight: bool = False):
    """Render a single recommendation section card."""
    border_color = "#b8dba8" if not highlight else "#4a8c3f"
    bg_color     = "white"   if not highlight else "#f0f8ec"

    st.markdown(
        f"""
        <div class="rec-section" style="border-color:{border_color}; background:{bg_color};">
            <h4>{title}</h4>
            {f'<p style="color:#6b7c61; font-size:0.82rem; margin:-4px 0 8px 0;">{subtitle}</p>' if subtitle else ""}
            <p>{content}</p>
        </div>
        """,
        unsafe_allow_html=True,
    )
